import{_ as o,o as a,c as t,a2 as r}from"./chunks/framework.B8bWmLDN.js";const h=JSON.parse('{"title":"診斷訊息","description":"","frontmatter":{},"headers":[],"relativePath":"zh-tw/reference/diagnostics.md","filePath":"zh-tw/reference/diagnostics.md","lastUpdated":1786769382000}'),s={name:"zh-tw/reference/diagnostics.md"};function c(d,e,n,i,p,l){return a(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="診斷訊息" tabindex="-1">診斷訊息 <a class="header-anchor" href="#診斷訊息" aria-label="Permalink to &quot;診斷訊息&quot;">​</a></h1><p>本頁列出 emitter 會回報的所有警告與錯誤，附原因與修法。診斷代碼在 compiler 輸出中顯示為 <code>tsp-asyncapi/&lt;code&gt;</code>。</p><p>所有診斷共用一條設計原則：<strong>emitter 絕不靜默丟棄或靜默改寫你的意圖。</strong> 無法表達的內容，一律以警告省略，或回報錯誤。</p><h2 id="錯誤" tabindex="-1">錯誤 <a class="header-anchor" href="#錯誤" aria-label="Permalink to &quot;錯誤&quot;">​</a></h2><h3 id="duplicate-schema-key" tabindex="-1"><code>duplicate-schema-key</code> <a class="header-anchor" href="#duplicate-schema-key" aria-label="Permalink to &quot;`duplicate-schema-key`&quot;">​</a></h3><blockquote><p>Duplicate schema name: &#39;&lt;name&gt;&#39;. Check @friendlyName decorators and overlap with types in TypeSpec or service namespace.</p></blockquote><p>兩個宣告解析到同一個 <code>components.schemas</code> key。常見原因：兩個 <code>@friendlyName</code> 解析成同一字串；或 model 名稱撞到 template 具現化的推導名稱（例如已宣告 <code>model PageString</code>，又使用 <code>Page&lt;string&gt;</code>）。</p><p><strong>修法：</strong> 改掉其中一個宣告的名稱，或給其中一個不同的 <code>@friendlyName</code>。emitter 絕不自動改名。</p><h3 id="unsupported-payload-type" tabindex="-1"><code>unsupported-payload-type</code> <a class="header-anchor" href="#unsupported-payload-type" aria-label="Permalink to &quot;`unsupported-payload-type`&quot;">​</a></h3><blockquote><p>This emitter does not support a &lt;kind&gt; here. Use a model, scalar, enum, union, or literal value instead.</p></blockquote><p>屬性或 payload 位置指到 schema 層無法轉換的 TypeSpec 實體，例如 <code>Interface</code>、<code>Namespace</code>、<code>Operation</code>。compiler 本身不會拒絕這種寫法，只有 emitter 會。</p><p><strong>修法：</strong> 改用 model、scalar、enum、union 或字面值型別。</p><h3 id="unrepresentable-circular-reference" tabindex="-1"><code>unrepresentable-circular-reference</code> <a class="header-anchor" href="#unrepresentable-circular-reference" aria-label="Permalink to &quot;`unrepresentable-circular-reference`&quot;">​</a></h3><blockquote><p>This anonymous type refers back to itself with no named type in between. A plain (non-$ref) schema cannot express that cycle. Give the type a name so it can be referenced through $ref instead.</p></blockquote><p>匿名型別繞回自己，例如 <code>alias Foo = { a: Foo };</code>。匿名型別只能內聯（沒有 <code>components.schemas</code> 項目），而內聯 schema 無法表達循環。</p><p><strong>修法：</strong> 把匿名型別改成具名 <code>model</code>。具名型別之間以 <code>$ref</code> 互相引用，循環沒有問題。</p><h3 id="duplicate-message-key" tabindex="-1"><code>duplicate-message-key</code> <a class="header-anchor" href="#duplicate-message-key" aria-label="Permalink to &quot;`duplicate-message-key`&quot;">​</a></h3><blockquote><p>Duplicate message name: &#39;&lt;name&gt;&#39;. Two @message models resolve to the same components.messages key. Pass an explicit name to @message on one of them.</p></blockquote><p>兩個 <code>@message</code> model 解析到同一個 <code>components.messages</code> key。常見原因：不同 namespace 下的同名 model（message key 不帶 namespace 前綴，schema key 會帶）；或兩個 <code>@friendlyName</code> 解析成同一字串。</p><p>同一個 template 的兩個具現化算出同一個 key 不會回報——原始碼裡只有一個 <code>@message</code>，兩者也指向同一份輸出的 component。</p><p><strong>修法：</strong> 對其中一個的 <code>@message</code> 傳入明確名稱。</p><h3 id="duplicate-message-decorator" tabindex="-1"><code>duplicate-message-decorator</code> <a class="header-anchor" href="#duplicate-message-decorator" aria-label="Permalink to &quot;`duplicate-message-decorator`&quot;">​</a></h3><blockquote><p>@message is applied to this model more than once. Only one application takes effect, and the rest are discarded. Remove the extra @message.</p></blockquote><p><code>@message</code> 不可重複標記。疊加時只會保留其中一次，其餘名稱不會進到文件裡。</p><p><strong>修法：</strong> 移除多餘的 <code>@message</code>。</p><h3 id="duplicate-server-name" tabindex="-1"><code>duplicate-server-name</code> <a class="header-anchor" href="#duplicate-server-name" aria-label="Permalink to &quot;`duplicate-server-name`&quot;">​</a></h3><blockquote><p>Duplicate server name: &#39;&lt;name&gt;&#39;. Each @server on a namespace needs its own name, because the name is the key of that server in the emitted document. This @server was dropped, and the first one with this name in source order was kept.</p></blockquote><p>同一個 namespace 上兩個 <code>@server</code> 用了同一個名稱。名稱就是 <code>servers</code> map 的 key，兩者會互相碰撞。emitter 絕不靜默挑一個。</p><p><strong>修法：</strong> 改掉其中一個的名稱。</p><h3 id="empty-server-field" tabindex="-1"><code>empty-server-field</code> <a class="header-anchor" href="#empty-server-field" aria-label="Permalink to &quot;`empty-server-field`&quot;">​</a></h3><blockquote><p>Empty server field: &#39;&lt;field&gt;&#39;. AsyncAPI requires a value for this field on every server. This @server was dropped.</p></blockquote><p><code>host</code> 或 <code>protocol</code> 是空字串，或只有空白字元。兩者都是 Server Object 的必填欄位。空值可以通過型別檢查，卻會產出不合規的文件，因此整個 server 被丟棄。</p><p><strong>修法：</strong> 給該欄位實際的值。</p><h3 id="invalid-server-name" tabindex="-1"><code>invalid-server-name</code> <a class="header-anchor" href="#invalid-server-name" aria-label="Permalink to &quot;`invalid-server-name`&quot;">​</a></h3><blockquote><p>Invalid server name: &#39;&lt;name&gt;&#39;. AsyncAPI only allows letters, digits, &#39;_&#39;, and &#39;-&#39; in a server name. This @server was dropped.</p></blockquote><p>名稱超出 AsyncAPI 允許的根層 <code>servers</code> map key 字元集。此字元集比 Components Object 的更嚴格，不允許點號。</p><p><strong>修法：</strong> 改用只含英文字母、數字、<code>_</code>、<code>-</code> 的名稱。emitter 絕不自動改名，因為那會靜默換掉你要求的 key。</p><h2 id="警告" tabindex="-1">警告 <a class="header-anchor" href="#警告" aria-label="Permalink to &quot;警告&quot;">​</a></h2><h3 id="message-key-shadows-schema-key" tabindex="-1"><code>message-key-shadows-schema-key</code> <a class="header-anchor" href="#message-key-shadows-schema-key" aria-label="Permalink to &quot;`message-key-shadows-schema-key`&quot;">​</a></h3><blockquote><p>Message name &#39;&lt;name&gt;&#39; is also the components.schemas key of a different type, so a reader can misread this message as describing that type. A message key drops the namespace prefix that a schema key keeps, which makes the two overlap. Pass a different name to @message.</p></blockquote><p>文件本身仍然合法——<code>components.messages</code> 與 <code>components.schemas</code> 是兩個獨立的 map，實際上沒有撞到。風險在讀的人：<code>components.messages.Sales.Ev</code> 與 <code>components.schemas[&quot;Sales.Ev&quot;]</code> 看起來像同一個東西，描述的卻是不同型別。</p><p><strong>修法：</strong> 對 <code>@message</code> 傳入不同的名稱。</p><h3 id="sanitized-message-key" tabindex="-1"><code>sanitized-message-key</code> <a class="header-anchor" href="#sanitized-message-key" aria-label="Permalink to &quot;`sanitized-message-key`&quot;">​</a></h3><blockquote><p>Message name &#39;&lt;requested&gt;&#39; is not a legal components.messages key, so it was emitted as &#39;&lt;emitted&gt;&#39;. A key may only use the characters a-z, A-Z, 0-9, &#39;.&#39;, &#39;-&#39;, and &#39;_&#39;.</p></blockquote><p>傳給 <code>@message</code> 的名稱超出 Components Object 的合法字元集，emitter 已把違規字元編碼。因此實際輸出的 key 並不是當初要求的字串。</p><p><strong>修法：</strong> 改用只含 <code>a-z</code>、<code>A-Z</code>、<code>0-9</code>、<code>.</code>、<code>-</code>、<code>_</code> 的名稱。</p><h3 id="server-outside-service" tabindex="-1"><code>server-outside-service</code> <a class="header-anchor" href="#server-outside-service" aria-label="Permalink to &quot;`server-outside-service`&quot;">​</a></h3><blockquote><p>Server &#39;&lt;name&gt;&#39; on namespace &#39;&lt;namespace&gt;&#39; was dropped. This emitter reads the servers of the service namespace only. Move this @server to the service namespace this document is emitted from.</p></blockquote><p><code>@server</code> 標在非本文件 service namespace 的 namespace 上。emitter 只讀 service namespace 的 server，來源與 <code>info</code> 相同。</p><p><strong>修法：</strong> 把 <code>@server</code> 移到 service namespace，或用 <code>@@server</code> 從目前位置 augment 過去。</p><h3 id="multiple-services" tabindex="-1"><code>multiple-services</code> <a class="header-anchor" href="#multiple-services" aria-label="Permalink to &quot;`multiple-services`&quot;">​</a></h3><blockquote><p>Multiple services found. AsyncAPI only supports one service per document. The first one will be used.</p></blockquote><p>多個 namespace 都標了 <code>@service</code>。emitter 採用第一個，忽略其餘。</p><p><strong>修法：</strong> 一次編譯保留一個 <code>@service</code>，或把 service 拆成多次 <code>tsp compile</code>。</p><h3 id="unserializable-example" tabindex="-1"><code>unserializable-example</code> <a class="header-anchor" href="#unserializable-example" aria-label="Permalink to &quot;`unserializable-example`&quot;">​</a></h3><blockquote><p>This @example could not be serialized to JSON and was omitted from the emitted schema.</p></blockquote><p><code>@example</code> 的值含有 compiler 無法序列化成純 JSON 的內容（不支援的 scalar constructor、格式錯誤的 <code>duration.fromISO(...)</code> 等）。該 example 被丟棄，schema 本身不受影響。</p><p><strong>修法：</strong> 把 example 值簡化成 JSON 可表示的內容。</p><h3 id="unrepresentable-numeric-constraint" tabindex="-1"><code>unrepresentable-numeric-constraint</code> <a class="header-anchor" href="#unrepresentable-numeric-constraint" aria-label="Permalink to &quot;`unrepresentable-numeric-constraint`&quot;">​</a></h3><blockquote><p>This @&lt;decorator&gt; constraint could not be represented as a JSON number (its value overflows or loses precision as a JS number) and was omitted from the emitted schema.</p></blockquote><p><code>@minValue</code> / <code>@maxValue</code> / <code>@minLength</code> 等的邊界值以 JavaScript number 表示時溢位或掉精度，例如 <code>int64</code> 上的 <code>@maxValue(9223372036854775807)</code>。該關鍵字被省略，不會輸出壞掉的值。</p><p><strong>修法：</strong> 改用 double 可精確表示的邊界值（±2^53 以內），或移除該限制。</p><h3 id="unsupported-temporal-range-constraint" tabindex="-1"><code>unsupported-temporal-range-constraint</code> <a class="header-anchor" href="#unsupported-temporal-range-constraint" aria-label="Permalink to &quot;`unsupported-temporal-range-constraint`&quot;">​</a></h3><blockquote><p>This @&lt;decorator&gt; constraint targets a date/time/duration value, which draft-07 JSON Schema cannot express as a <code>minimum</code>/<code>maximum</code>, and was omitted from the emitted schema.</p></blockquote><p><code>@minValue</code> / <code>@maxValue</code> 標在時間類 scalar（<code>utcDateTime</code>、<code>plainDate</code>、<code>duration</code> 等）上。這些 scalar 輸出為 <code>type: string</code>，draft-07 沒有能約束字串日期範圍的關鍵字。</p><p><strong>修法：</strong> 移除該限制，或改以 <code>@doc</code> 用文字描述。</p><h3 id="missing-discriminator-property" tabindex="-1"><code>missing-discriminator-property</code> <a class="header-anchor" href="#missing-discriminator-property" aria-label="Permalink to &quot;`missing-discriminator-property`&quot;">​</a></h3><blockquote><p>@discriminator(&quot;&lt;property&gt;&quot;) names a property that is not defined on this model. AsyncAPI requires the discriminating property to be defined here, so <code>discriminator</code> was omitted from the emitted schema.</p></blockquote><p><strong>修法：</strong> 在該 model（或祖先）上宣告這個屬性，或修正 <code>@discriminator</code> 裡的屬性名稱。指名用的是 <strong>TypeSpec</strong> 屬性名稱，不是 <code>@encodedName</code> 的 wire name。</p><h3 id="optional-discriminator-property" tabindex="-1"><code>optional-discriminator-property</code> <a class="header-anchor" href="#optional-discriminator-property" aria-label="Permalink to &quot;`optional-discriminator-property`&quot;">​</a></h3><blockquote><p>@discriminator(&quot;&lt;property&gt;&quot;) names a property that is optional on this model. AsyncAPI requires the discriminating property to be required, so <code>discriminator</code> was omitted from the emitted schema.</p></blockquote><p><strong>修法：</strong> 把 discriminating 屬性改成必填（移除 <code>?</code>）。</p><h3 id="encoded-name-override-conflict" tabindex="-1"><code>encoded-name-override-conflict</code> <a class="header-anchor" href="#encoded-name-override-conflict" aria-label="Permalink to &quot;`encoded-name-override-conflict`&quot;">​</a></h3><p>覆寫屬性的 <code>@encodedName</code> 與祖先同名屬性的 wire name 不同。一般的 <code>allOf: [$ref Base, own]</code> 形狀會同時要求<strong>兩個</strong> wire name，導致任何合法 payload 都被拒絕。emitter 改為攤平該 model 的 schema（繼承屬性內聯，不再 <code>$ref</code> 基底）。</p><p><strong>修法：</strong> 讓覆寫屬性用與祖先相同的 <code>@encodedName</code>，或只在其中一層改名。</p><h3 id="never-typed-property-override" tabindex="-1"><code>never-typed-property-override</code> <a class="header-anchor" href="#never-typed-property-override" aria-label="Permalink to &quot;`never-typed-property-override`&quot;">​</a></h3><p>屬性宣告為 <code>never</code> 以移除繼承屬性，但基底的 <code>$ref</code> 分支仍會要求它。emitter 同樣改為攤平 schema（<code>never</code> 屬性省略）。</p><p><strong>修法：</strong> 若攤平可接受則不需處理，此警告只說明形狀改變。否則調整繼承結構，讓該屬性一開始就不被繼承。</p>',78)])])}const u=o(s,[["render",c]]);export{h as __pageData,u as default};
